#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(optparse); library(jsonlite)})
`%||%` <- function(x,y) if(is.null(x)||!length(x)) y else x
op <- parse_args(OptionParser(option_list=list(
  make_option('--input',type='character'),make_option('--params',type='character'),make_option('--output',type='character'),
  make_option('--row-annot',dest='row_annot',type='character'),make_option('--col-annot',dest='col_annot',type='character'),
  make_option('--panel-groups',dest='panel_groups_file',type='character'),make_option('--labels',type='character'))))
out <- op$output %||% getwd(); dir.create(out,recursive=TRUE,showWarnings=FALSE)
unlink(file.path(out,c('result.svg','result.pdf','result.png','result.html','figure.json','matrix_data_used.csv','row_order.csv','column_order.csv','error.json')),force=TRUE)
write_log <- function(x) cat(sprintf('[%s] %s\n',format(Sys.time(),'%F %T'),x),file=file.path(out,'run.log'),append=TRUE)
fail <- function(x,detail='',suggestion='Check the input and params.json.') { writeLines(toJSON(list(error=x,detail=detail,suggestion=suggestion),auto_unbox=TRUE,pretty=TRUE),file.path(out,'error.json')); write_log(paste(x,detail)); quit(status=1) }
readtab <- function(f) { if(is.null(f)||!file.exists(f)) fail('Input file not found',as.character(f)); if(tolower(tools::file_ext(f))%in%c('tsv','txt')) read.delim(f,check.names=FALSE,stringsAsFactors=FALSE) else read.csv(f,check.names=FALSE,stringsAsFactors=FALSE) }
flat_params <- function(x) { z<-x; for(n in names(x)) if(is.list(x[[n]])&&!is.data.frame(x[[n]])) for(k in names(x[[n]])) if(is.null(z[[k]])) z[[k]]<-x[[n]][[k]]; z }
bool <- function(x,d=FALSE) { if(is.null(x)) return(d); if(is.logical(x)) return(isTRUE(x[1])); tolower(as.character(x[1]))%in%c('true','t','yes','y','1','on') }
vec <- function(x) { if(is.null(x)) return(character()); x<-unlist(x,use.names=FALSE); if(length(x)==1&&grepl(',',x,fixed=TRUE)) x<-strsplit(x,',',fixed=TRUE)[[1]]; trimws(as.character(x)) }
num <- function(x,d=NA_real_) { y<-suppressWarnings(as.numeric(unlist(x,use.names=FALSE))[1]); if(is.finite(y)) y else d }
nums <- function(x) suppressWarnings(as.numeric(unlist(x,use.names=FALSE)))
param <- function(p,n,d=NULL) if(!is.null(p[[n]])) p[[n]] else d
panel_outer <- function(x,y,FUN) matrix(unlist(lapply(seq_along(x),function(i) vapply(seq_along(y),function(j) FUN(x[i],y[j]),character(1))),use.names=FALSE),nrow=length(x),byrow=TRUE)
outer <- panel_outer
palette_values <- function(p,vals) { known<-list(viridis=c('#440154','#21908C','#FDE725'),plasma=c('#0D0887','#CC4778','#F0F921'),magma=c('#000004','#B73779','#FCFDBF'),inferno=c('#000004','#B63679','#FCFFA4'),cividis=c('#00204C','#7A7B56','#FDE737'),blue_white_red=c('#2166AC','#F7F7F7','#B2182B')); scheme<-tolower(as.character(param(p,'palette','viridis'))[1]); cols<-if(scheme=='custom') as.character(unlist(param(p,'colors',c('#2166AC','#F7F7F7','#B2182B')))) else known[[scheme]]; if(is.null(cols)||length(cols)<2) cols<-known$viridis; lim<-nums(param(p,'limits',NULL)); lim<-lim[is.finite(lim)]; if(length(lim)!=2) lim<-range(vals,na.rm=TRUE); if(!all(is.finite(lim))||lim[1]==lim[2]) lim<-c(lim[1]-.5,lim[2]+.5); list(colors=grDevices::colorRampPalette(cols)(256),limits=lim,name=scheme) }
panel_palette <- function(p,n,vals,shared) { pp<-param(p,'panel_palettes',NULL); s<-if(is.list(pp)&&!is.null(pp[[n]])) pp[[n]] else NULL; if(is.null(s)) return(shared); q<-p; if(is.character(s)&&length(s)==1) q$palette<-s else if(is.list(s)) for(k in names(s)) q[[k]]<-s[[k]]; palette_values(q,vals) }
distance_matrix <- function(x,m) { if(m=='correlation') { z<-suppressWarnings(cor(t(x),use='pairwise.complete.obs')); z[!is.finite(z)]<-0; as.dist(1-z) } else stats::dist(x,method=m) }
annotation_info <- function(df,ids,p,side) { if(is.null(df)||!nrow(df)||!bool(param(p,paste0(side,'_annotation_show'),TRUE),TRUE)) return(list()); id<-as.character(df[[1]]); z<-df[match(ids,id),-1,drop=FALSE]; z<-z[,vapply(z,function(x) any(!is.na(x)&nzchar(as.character(x))),logical(1)),drop=FALSE]; lapply(names(z),function(n) { x<-z[[n]]; a<-suppressWarnings(as.numeric(as.character(x))); isnum<-sum(!is.na(a))==length(a[!is.na(a)])&&sum(!is.na(a))>0; if(isnum) { r<-range(a,na.rm=TRUE); if(diff(r)==0) r<-r+c(-.5,.5); cc<-grDevices::colorRampPalette(c('#F7FBFF','#6BAED6','#08306B'))(256); cell<-cc[pmax(1,pmin(256,1+round(255*(a-r[1])/diff(r))))] } else { lev<-unique(as.character(x)); cc<-setNames(grDevices::hcl.colors(max(1,length(lev)),'Set 2'),lev); cell<-unname(cc[as.character(x)]) }; list(name=n,cell_colors=cell) }) }
panel_definition <- function(p,ids,ca) { raw<-param(p,'panel_groups',NULL); g<-NULL; if(!is.null(raw)) { if(is.list(raw)&&!is.null(names(raw))) { g<-rep(NA_character_,length(ids)); names(g)<-ids; for(n in names(raw)) g[match(vec(raw[[n]]),ids)]<-n } else if(length(unlist(raw,use.names=FALSE))==length(ids)) g<-as.character(unlist(raw,use.names=FALSE)) }; col<-as.character(param(p,'panel_group_column',''))[1]; if((is.null(g)||all(is.na(g)))&&nzchar(col)&&!is.null(ca)&&col%in%names(ca)) g<-as.character(ca[match(ids,as.character(ca[[1]])),col]); if(is.null(g)||!length(g)||all(is.na(g))||!any(nzchar(g))) g<-rep('All',length(ids)); g[is.na(g)|!nzchar(g)]<-'Other'; present<-unique(g); requested<-vec(param(p,'panel_order',NULL)); ord<-c(intersect(requested,present),setdiff(present,requested)); cols<-lapply(ord,function(n) ids[g==n]); names(cols)<-ord; list(enabled=!(length(ord)==1&&ord[1]=='All'&&is.null(raw)&&!nzchar(col)),groups=g,order=ord,columns=cols) }
main <- function() {
 panel <- list(enabled=TRUE)
 if(is.null(op$input)||!file.exists(op$input)) fail('Input file not found',as.character(op$input)); if(is.null(op$params)||!file.exists(op$params)) fail('Params file not found',as.character(op$params))
 p<-flat_params(fromJSON(op$params,simplifyVector=FALSE)); d<-readtab(op$input); rowcol<-as.character(param(p,'row_id_column',names(d)[1]))[1]; if(!rowcol%in%names(d)) fail('row_id_column not found',rowcol); start<-param(p,'matrix_start_column',2); start<-if(is.character(start)) match(start,names(d)) else as.integer(start); ids<-make.unique(as.character(d[[rowcol]])); x<-d[,start:ncol(d),drop=FALSE]; mat<-as.matrix(data.frame(lapply(x,function(v)suppressWarnings(as.numeric(as.character(v)))))); rownames(mat)<-ids; colnames(mat)<-names(x); if(bool(param(p,'transpose',FALSE))) { mat<-t(mat); row_ids<-colnames(x); col_ids<-ids } else { row_ids<-ids; col_ids<-colnames(x) }; dimnames(mat)<-list(make.unique(as.character(row_ids)),make.unique(as.character(col_ids)))
 keep<-function(h,inc,exc) { if(length(inc)) h<-intersect(h,inc); if(length(exc)) h<-setdiff(h,exc); h }; mat<-mat[keep(rownames(mat),vec(param(p,'rows_include')),vec(param(p,'rows_exclude'))),keep(colnames(mat),vec(param(p,'columns_include')),vec(param(p,'columns_exclude'))),drop=FALSE]; na<-tolower(as.character(param(p,'na_action','impute'))[1]); if(na=='error'&&anyNA(mat)) fail('Missing values found'); if(na=='omit') mat<-mat[rowSums(is.na(mat))==0,colSums(is.na(mat))==0,drop=FALSE] else if(na=='impute') mat[is.na(mat)]<-num(param(p,'impute_value',0),0); if(!nrow(mat)||!ncol(mat)) fail('Matrix is empty after filtering')
 scale_mode<-tolower(as.character(param(p,'scale','none'))[1]); sf<-function(v) { s<-sd(v,na.rm=TRUE); if(!is.finite(s)||s==0) rep(0,length(v)) else (v-mean(v,na.rm=TRUE))/s }; if(scale_mode=='row') mat<-t(apply(mat,1,sf)) else if(scale_mode=='column') mat<-apply(mat,2,sf); dimnames(mat)<-list(make.unique(as.character(row_ids))[match(rownames(mat),make.unique(as.character(row_ids)))],colnames(mat)); if(any(!is.finite(mat),na.rm=TRUE)) mat[!is.finite(mat)]<-0
 distm<-tolower(as.character(param(p,'distance_method','euclidean'))[1]); method<-as.character(param(p,'cluster_method','complete'))[1]; cluster<-function(z,en,manual) { if(length(manual)) return(c(intersect(manual,rownames(z)),setdiff(rownames(z),manual))); if(en&&nrow(z)>1) { h<-tryCatch(hclust(distance_matrix(z,distm),method=method),error=function(e) NULL); if(!is.null(h)) return(rownames(z)[h$order]) }; rownames(z) }; ro<-cluster(mat,bool(param(p,'cluster_rows',TRUE),TRUE),vec(param(p,'row_order'))); co<-cluster(t(mat),bool(param(p,'cluster_columns',TRUE),TRUE),vec(param(p,'column_order'))); mat<-mat[ro,co,drop=FALSE]
 write.csv(mat,file.path(out,'matrix_data_used.csv')); write.csv(data.frame(row_id=ro),file.path(out,'row_order.csv'),row.names=FALSE); write.csv(data.frame(column_id=co),file.path(out,'column_order.csv'),row.names=FALSE); ra<-if(!is.null(op$row_annot)) readtab(op$row_annot) else if(!is.null(param(p,'row_annotation_file'))) readtab(param(p,'row_annotation_file')) else NULL; ca<-if(!is.null(op$col_annot)) readtab(op$col_annot) else if(!is.null(param(p,'column_annotation_file'))) readtab(param(p,'column_annotation_file')) else NULL; pg<-if(!is.null(op$panel_groups_file)) readtab(op$panel_groups_file) else NULL; if(!is.null(pg)&&ncol(pg)>=2) { names(pg)[1:2]<-c('panel_column','panel'); ca<-if(is.null(ca)) pg else merge(ca,pg[,1:2],by.x=names(ca)[1],by.y='panel_column',all.x=TRUE,sort=FALSE) }; ri<-annotation_info(ra,ro,p,'row'); ci<-annotation_info(ca,co,p,'column'); panels<-panel_definition(p,co,ca); shared<-palette_values(p,as.vector(mat)); mode<-tolower(as.character(param(p,'panel_scales','shared'))[1]); if(!mode%in%c('none','shared','per_panel')) mode<-'shared'; pcols<-lapply(panels$order,function(n) if(mode=='per_panel') panel_palette(p,n,mat[,panels$columns[[n]],drop=FALSE],shared) else shared); names(pcols)<-panels$order
 draw<-function(device) { library(grid); w<-num(param(p,'width',12),12); h<-num(param(p,'height',9),9); if(device=='svg') svg(file.path(out,'result.svg'),w,h); if(device=='pdf') pdf(file.path(out,'result.pdf'),w,h,useDingbats=FALSE); if(device=='png') png(file.path(out,'result.png'),w,h,units='in',res=as.integer(num(param(p,'dpi',300),300))); on.exit(dev.off()); grid.newpage(); grid.rect(gp=gpar(fill=param(p,'plot_background','#FFFFFF'),col=NA)); nr<-nrow(mat); gap<-num(param(p,'panel_gap',.015),.015); widths<-vapply(panels$columns,length,integer(1)); mx0<-.24; mx1<-.79; if(bool(param(p,'show_row_dendrogram',TRUE),TRUE)) mx0<-mx0+.08; aw<-if(length(ri)) num(param(p,'row_annotation_width',.12),.12) else 0; mx0<-mx0+aw; total<-sum(widths)+max(0,length(widths)-1)*gap*100; xstart<-mx0; usable<-mx1-xstart; header<-if(panels$enabled&&bool(param(p,'panel_header_show',TRUE),TRUE)) num(param(p,'panel_header_height',.055),.055) else 0; y0<-.17; y1<-.78; if(length(ci)) y1<-y1-num(param(p,'column_annotation_height',.16),.16); starts<-cumsum(c(0,head(widths,-1)+gap*100))/total*usable+xstart; for(k in seq_along(panels$order)) { js<-match(panels$columns[[k]],co); xa<-starts[k]; xb<-xa+usable*widths[k]/total; for(i in seq_len(nr)) for(j in seq_along(js)) { xx<-xa+(j-.5)*(xb-xa)/length(js); yy<-y1-(i-.5)*(y1-y0)/nr; z<-mat[i,js[j]]; pp<-pcols[[k]]; cc<-if(is.na(z)) param(p,'na_color','#D9D9D9') else pp$colors[max(1,min(256,1+round(255*(z-pp$limits[1])/diff(pp$limits))))]; grid.rect(xx,yy,(xb-xa)/length(js),(y1-y0)/nr,gp=gpar(fill=cc,col=if(bool(param(p,'panel_border_show',param(p,'cell_border_show',TRUE)),TRUE)) param(p,'panel_border_color',param(p,'cell_border_color','#FFFFFF')) else NA,lwd=num(param(p,'panel_border_width',param(p,'cell_border_width',.2)),.2))) }; if(panel$enabled){}; if(panels$enabled&&bool(param(p,'panel_header_show',TRUE),TRUE)) grid.rect((xa+xb)/2,y1+header/2,xb-xa,header,gp=gpar(fill=param(p,'panel_header_fill','#EAEAEA'),col=NA)); if(panels$enabled&&bool(param(p,'panel_header_show',TRUE),TRUE)) grid.text(panels$order[k],(xa+xb)/2,y1+header/2,gp=gpar(col=param(p,'panel_header_color','#222222'),fontsize=num(param(p,'panel_header_size',9),9),fontface=param(p,'panel_header_face','bold'))); if(bool(param(p,'column_labels_show',TRUE),TRUE)) for(j in seq_along(js)) grid.text(co[js[j]],xa+(j-.5)*(xb-xa)/length(js),y0-.012,rot=num(param(p,'panel_label_angle',param(p,'column_label_angle',45)),45),just='right',gp=gpar(fontsize=num(param(p,'panel_label_size',param(p,'column_label_size',8)),8),col=param(p,'panel_label_color',param(p,'column_label_color','#222222')))) }; if(bool(param(p,'row_labels_show',TRUE),TRUE)) for(i in seq_len(nr)) grid.text(ro[i],mx0-.008,y1-(i-.5)*(y1-y0)/nr,just='right',gp=gpar(fontsize=num(param(p,'row_label_size',8),8),col=param(p,'row_label_color','#222222'))); if(bool(param(p,'title_show',TRUE),TRUE)) grid.text(param(p,'title','Interactive Clustered Heatmap'),.5,.96,gp=gpar(fontsize=num(param(p,'title_size',16),16),fontface=param(p,'title_face','bold'))); if(bool(param(p,'colorbar_show',TRUE),TRUE)) { x<-.88; grid.rect(x,.5,.025,.35,gp=gpar(fill=rev(shared$colors),col=NA)); grid.text(param(p,'legend_title',param(p,'colorbar_title','Value')),x+.045,.7,rot=90,gp=gpar(fontsize=9)); grid.text(formatC(shared$limits[1],digits=3),x+.045,.32,gp=gpar(fontsize=8)); grid.text(formatC(shared$limits[2],digits=3),x+.045,.68,gp=gpar(fontsize=8)) } }
 draw <- function(device) {
   library(grid); w<-num(param(p,'width',12),12); h<-num(param(p,'height',9),9)
   if(device=='svg') svg(file.path(out,'result.svg'),w,h); if(device=='pdf') pdf(file.path(out,'result.pdf'),w,h,useDingbats=FALSE); if(device=='png') png(file.path(out,'result.png'),w,h,units='in',res=as.integer(num(param(p,'dpi',300),300))); on.exit(dev.off()); grid.newpage(); grid.rect(gp=gpar(fill=param(p,'plot_background','#FFFFFF'),col=NA))
   nr<-nrow(mat); gap<-num(param(p,'panel_gap',.015),.015); widths<-vapply(panels$columns,length,integer(1)); mx0<-.24; mx1<-.79; if(bool(param(p,'show_row_dendrogram',TRUE),TRUE)) mx0<-mx0+.08; if(length(ri)) mx0<-mx0+num(param(p,'row_annotation_width',.12),.12); total<-sum(widths)+max(0,length(widths)-1)*gap*100; usable<-mx1-mx0; header<-if(panels$enabled&&bool(param(p,'panel_header_show',TRUE),TRUE)) num(param(p,'panel_header_height',.055),.055) else 0; y0<-.17; y1<-.78; if(length(ci)) y1<-y1-num(param(p,'column_annotation_height',.16),.16); starts<-cumsum(c(0,head(widths,-1)+gap*100))/total*usable+mx0
   for(k in seq_along(panels$order)) { panel_ids<-as.character(panels$columns[[k]]); js<-match(panel_ids,co); js<-js[is.finite(js)]; xa<-starts[k]; xb<-xa+usable*length(js)/total; cw<-(xb-xa)/length(js); ch<-(y1-y0)/nr; for(i in seq_len(nr)) for(j in seq_along(js)) { z<-as.numeric(mat[i,js[j]])[1]; pp<-pcols[[k]]; idx<-if(is.na(z)) NA_integer_ else max(1,min(256,1+round(255*(z-pp$limits[1])/diff(pp$limits)))); fill<-if(is.na(idx)) as.character(param(p,'na_color','#D9D9D9'))[1] else as.character(pp$colors[idx])[1]; grid.rect(x=as.numeric(xa+(j-.5)*cw),y=as.numeric(y1-(i-.5)*ch),width=as.numeric(cw),height=as.numeric(ch),gp=gpar(fill=fill,col=if(bool(param(p,'panel_border_show',param(p,'cell_border_show',TRUE)),TRUE)) as.character(param(p,'panel_border_color',param(p,'cell_border_color','#FFFFFF')))[1] else NA,lwd=num(param(p,'panel_border_width',param(p,'cell_border_width',.2)),.2))) }; if(panels$enabled&&bool(param(p,'panel_header_show',TRUE),TRUE)) { grid.rect(x=(xa+xb)/2,y=y1+header/2,width=xb-xa,height=header,gp=gpar(fill=as.character(param(p,'panel_header_fill','#EAEAEA'))[1],col=NA)); grid.text(as.character(panels$order[k]),x=(xa+xb)/2,y=y1+header/2,gp=gpar(col=as.character(param(p,'panel_header_color','#222222'))[1],fontsize=num(param(p,'panel_header_size',9),9),fontface=param(p,'panel_header_face','bold'))) }; if(bool(param(p,'column_labels_show',TRUE),TRUE)) for(j in seq_along(js)) grid.text(as.character(co[js[j]]),x=xa+(j-.5)*cw,y=y0-.012,rot=num(param(p,'panel_label_angle',param(p,'column_label_angle',45)),45),just='right',gp=gpar(fontsize=num(param(p,'panel_label_size',param(p,'column_label_size',8)),8),col=as.character(param(p,'panel_label_color',param(p,'column_label_color','#222222')))[1])) }
   if(bool(param(p,'row_labels_show',TRUE),TRUE)) for(i in seq_len(nr)) grid.text(as.character(ro[i]),x=mx0-.008,y=y1-(i-.5)*(y1-y0)/nr,just='right',gp=gpar(fontsize=num(param(p,'row_label_size',8),8),col=as.character(param(p,'row_label_color','#222222'))[1])); if(bool(param(p,'title_show',TRUE),TRUE)) grid.text(as.character(param(p,'title','Interactive Clustered Heatmap'))[1],x=.5,y=.96,gp=gpar(fontsize=num(param(p,'title_size',16),16),fontface=param(p,'title_face','bold'))); if(bool(param(p,'colorbar_show',TRUE),TRUE)) { x<-.88; for(q in seq_len(64)) grid.rect(x=x,y=.325+(q-.5)*.35/64,width=.025,height=.35/64,gp=gpar(fill=as.character(shared$colors[257-q*4])[1],col=NA)); grid.text(as.character(param(p,'legend_title',param(p,'colorbar_title','Value')))[1],x=x+.045,y=.7,rot=90,gp=gpar(fontsize=9)); grid.text(formatC(shared$limits[1],digits=3),x=x+.045,y=.32,gp=gpar(fontsize=8)); grid.text(formatC(shared$limits[2],digits=3),x=x+.045,y=.68,gp=gpar(fontsize=8)) }
 }
 for(dev in c('svg','pdf','png')) draw(dev)
 if(bool(param(p,'interactive',TRUE),TRUE)&&requireNamespace('plotly',quietly=TRUE)&&requireNamespace('htmlwidgets',quietly=TRUE)) { pl<-plotly::plot_ly(); for(k in seq_along(panels$order)) { js<-match(panels$columns[[k]],co); z<-mat[,js,drop=FALSE]; ht<-outer(ro,co[js],function(r,c) sprintf('Panel: %s<br>Row: %s<br>Column: %s<br>Value: %s',panels$order[k],r,c,formatC(mat[r,c],digits=6,format='fg'))); pp<-pcols[[k]]; pl<-plotly::add_trace(pl,x=co[js],y=ro,z=z,type='heatmap',colorscale=pp$colors,zmin=pp$limits[1],zmax=pp$limits[2],text=ht,hoverinfo='text',showscale=k==1) }; pl<-plotly::layout(pl,title=param(p,'title','Interactive Clustered Heatmap'),yaxis=list(autorange='reversed'),xaxis=list(tickangle=num(param(p,'column_label_angle',45),45))); htmlwidgets::saveWidget(pl,file.path(out,'result.html'),selfcontained=TRUE) } else writeLines('<html><body><h1>Interactive Clustered Heatmap</h1><p>Plotly is unavailable; see result.png, result.svg, or result.pdf.</p></body></html>',file.path(out,'result.html'))
 fig<-list(plugin='interactive_clustered_heatmap_plot',title=param(p,'title','Interactive Clustered Heatmap'),matrix_dimensions=list(rows=nrow(mat),columns=ncol(mat)),scale=param(p,'scale','none'),cluster=list(rows=bool(param(p,'cluster_rows',TRUE),TRUE),columns=bool(param(p,'cluster_columns',TRUE),TRUE),distance_method=distm,cluster_method=method),row_order=ro,column_order=co,panels=list(enabled=panels$enabled,order=panels$order,columns=panels$columns,scales=mode),annotation_columns=list(rows=vapply(ri,function(x)x$name,character(1)),columns=vapply(ci,function(x)x$name,character(1))),numeric_range=range(mat,na.rm=TRUE),palette=shared$name,outputs=c('result.svg','result.pdf','result.png','result.html','figure.json','run.log','matrix_data_used.csv','row_order.csv','column_order.csv')); writeLines(toJSON(fig,auto_unbox=TRUE,pretty=TRUE),file.path(out,'figure.json')); unlink(file.path(out,'error.json'),force=TRUE); write_log(sprintf('Finished %d x %d clustered heatmap.',nrow(mat),ncol(mat))) }
 tryCatch(main(),error=function(e) fail('Clustered heatmap rendering failed',conditionMessage(e),'Check numeric matrix values, annotation IDs, and params.'))
